class s{intervalId=null;pollFn=null;fnName=null;intervalMs=1e4;constructor(){}startPolling(l,n=10,t){this.fnName=t||l.name||"[anonymous]",console.log(`Starting polling: ${this.fnName} every ${n}s`),this.pollFn=l,this.intervalMs=n*1e3,this.intervalId=window.setInterval(()=>{document.visibilityState==="visible"&&this.pollFn&&Promise.resolve(this.pollFn()).catch(i=>console.warn("Polling function threw:",i))},this.intervalMs)}stopPolling(){this.intervalId!==null&&(console.log(`Stop polling: ${this.fnName}`),clearInterval(this.intervalId),this.intervalId=null)}}export{s as P};
